(function(){"use strict";const lecture={"id":"ec214-l1","label":"Lecture 1 • Introduction to Economics","description":"Foundations, PPF, demand, supply and market equilibrium.","cumulativeId":"ec214-l1-full-v1","cumulativeLabel":"Full Lecture • Lecture 1","parts":[{"id":"ec214-l1-foundations-v1","label":"Part 1 • Foundations, Scarcity & Production Choices","description":"Economics, agents, choices, markets, goods, factors and paid incomes.","cards":[{"id":"economics","front":"What does economics study?","back":"Choices under scarcity, incentives, and how resources are coordinated to achieve objectives."},{"id":"consumer","front":"What scarce resource and objective define a consumer?","back":"Limited income/money; chooses consumption to maximize satisfaction or utility."},{"id":"firm","front":"What scarce resource and objective define a firm?","back":"Limited budget/resources; chooses production to maximize profit."},{"id":"government","front":"What is the government’s objective in the lecture framework?","back":"Use policies and budgets to maximize social welfare."},{"id":"what","front":"What does the economic question WHAT ask?","back":"Which goods or services will be produced."},{"id":"how","front":"What does the economic question HOW ask?","back":"Which production method and combination of productive resources will be used."},{"id":"for-whom","front":"What does FOR WHOM ask?","back":"Who receives output, linked to factor ownership, income, and purchasing power."},{"id":"self-social","front":"What is the lecture’s self-interest vs social-interest question?","back":"Whether choices made for private benefit also promote society’s overall interest."},{"id":"micro","front":"What does microeconomics focus on?","back":"Individual consumers, firms, individual markets, and policies affecting their choices."},{"id":"macro","front":"What does macroeconomics focus on?","back":"Aggregate national/global outcomes such as GDP, inflation, and employment."},{"id":"positive","front":"What is a positive statement?","back":"A testable statement about what is or how the economic world works."},{"id":"normative","front":"What is a normative statement?","back":"A judgment about what ought to be done or which outcome is preferable."},{"id":"ceteris","front":"What does ceteris paribus mean?","back":"Change one factor while holding other relevant factors constant to isolate cause and effect."},{"id":"scarcity","front":"What is scarcity?","back":"Available resources are insufficient to satisfy all wants, so choices must be made."},{"id":"free-scarce","front":"Can a free resource still be scarce?","back":"Yes. It is scarce if people cannot obtain as much as they want."},{"id":"incentive","front":"How do incentives relate to choice?","back":"They change the benefits or costs of alternatives and can change which option is chosen."},{"id":"market","front":"What is a market?","back":"An arrangement where buyers and sellers interact and transact at a price; it need not be a physical place."},{"id":"consumption-good","front":"What is a consumption good or service?","back":"A final good/service used by households for personal consumption."},{"id":"capital-good","front":"What is a capital good?","back":"A produced item used to help produce other goods or services, such as machinery."},{"id":"government-good","front":"What identifies a government good or service?","back":"It is produced or purchased for government activity or public provision."},{"id":"export-good","front":"What is an export good or service?","back":"Domestic production sold to buyers abroad."},{"id":"land","front":"What does Land mean as a factor of production?","back":"Natural resources or 'gifts of nature' used in production."},{"id":"labor","front":"What does Labor mean as a factor of production?","back":"Human time and effort used to produce goods and services."},{"id":"capital-factor","front":"What does Capital mean as a factor of production?","back":"Produced productive resources such as tools, machines, equipment, and buildings."},{"id":"entrepreneurship","front":"What does Entrepreneurship mean as a factor?","back":"Organizing other factors, making business decisions, and bearing residual business outcomes."},{"id":"factor-payments","front":"Match the four factors to paid incomes.","back":"Land→rent; Labor→wages; Capital→interest; Entrepreneurship→profit or loss."},{"id":"factor-payment-flow","front":"Why do factor payments matter for FOR WHOM?","back":"They become owners’ income and purchasing power, helping determine who can buy output."},{"id":"firm-cost-owner-income","front":"How can the same factor payment be viewed two ways?","back":"It is a cost to the firm and income to the factor owner."}]},{"id":"ec214-l1-costs-ppf-v1","label":"Part 2 • Opportunity Cost, Profit & PPF","description":"Economic cost/profit and complete PPF reading logic.","cards":[{"id":"opp-cost","front":"What is opportunity cost?","back":"The value of the next-best alternative forgone."},{"id":"opp-not-sum","front":"Is opportunity cost the sum of all forgone alternatives?","back":"No. It is only the next-best alternative."},{"id":"explicit-cost","front":"What is an explicit cost?","back":"A direct monetary payment recorded by the business."},{"id":"implicit-cost","front":"What is an implicit cost?","back":"A real economic cost without a separate cash payment, often a forgone alternative return."},{"id":"accounting-cost","front":"What is accounting cost?","back":"Explicit cost."},{"id":"economic-cost","front":"What is economic cost?","back":"Explicit cost + implicit cost."},{"id":"accounting-profit","front":"What is accounting profit?","back":"Revenue − explicit cost."},{"id":"economic-profit","front":"What is economic profit?","back":"Revenue − explicit cost − implicit cost."},{"id":"ppf-def","front":"What does a Production Possibilities Frontier show?","back":"The boundary between producible and currently unproducible combinations given resources and technology."},{"id":"ppf-attainable","front":"Which PPF points are attainable?","back":"Points on or inside the frontier."},{"id":"ppf-unattainable","front":"Which PPF points are currently unattainable?","back":"Points outside the frontier."},{"id":"ppf-efficient","front":"Which PPF points are productively efficient?","back":"Points on the frontier, where resources are fully used."},{"id":"ppf-inefficient","front":"What does a point inside the PPF mean?","back":"Attainable but inefficient: resources are idle or misallocated."},{"id":"ppf-tradeoff","front":"What does movement along the PPF imply?","back":"A tradeoff: gaining more of one good requires giving up some of the other."},{"id":"ppf-free-lunch","front":"When can a PPF move represent a 'free lunch'?","back":"Moving from an inefficient inside point toward the frontier using idle/misallocated resources."},{"id":"personal-ppf","front":"How does the lecture apply PPF logic to a student?","back":"More GPA may require giving up leisure or work income; that forgone benefit is opportunity cost."},{"id":"ppf-market-bridge","front":"What market model follows the PPF discussion?","back":"Buyers→Demand; sellers/resource owners→Supply; their interaction→Equilibrium."}]},{"id":"ec214-l1-demand-v1","label":"Part 3 • Demand","description":"Quantity demanded, law of demand, determinants, movement and shifts.","cards":[{"id":"qd","front":"What is quantity demanded (Qd)?","back":"The amount buyers are willing to purchase at a specific time."},{"id":"law-demand","front":"State the law of demand.","back":"Ceteris paribus: price rises→Qd falls; price falls→Qd rises."},{"id":"demand-slope","front":"Why does the demand curve slope downward?","back":"Because price and quantity demanded have a negative relationship, other things equal."},{"id":"normal","front":"How does higher income affect demand for a normal good?","back":"Demand increases; the demand curve shifts right."},{"id":"inferior","front":"How does higher income affect demand for an inferior good?","back":"Demand decreases; the demand curve shifts left."},{"id":"substitute","front":"If a substitute’s price rises, what happens to demand for this good?","back":"Demand for this good increases."},{"id":"complement","front":"If a complement’s price rises, what happens to demand for this good?","back":"Demand for this good decreases."},{"id":"taste","front":"How do stronger preferences affect demand?","back":"Demand increases."},{"id":"expect-demand","front":"If buyers expect the good’s future price to rise, what can happen now?","back":"Current demand rises in the lecture example."},{"id":"buyers","front":"How does a larger number of buyers affect market demand?","back":"Market demand increases."},{"id":"demand-movement","front":"What causes movement along a demand curve?","back":"A change in the good’s own current price."},{"id":"demand-shift","front":"What causes a demand curve shift?","back":"A non-price determinant: income, related-good prices, tastes, expectations, or number of buyers."},{"id":"demand-right","front":"What does a rightward demand shift mean?","back":"A greater quantity demanded at every price."},{"id":"demand-left","front":"What does a leftward demand shift mean?","back":"A smaller quantity demanded at every price."},{"id":"ev-oil","front":"What happens to oil demand if greater EV use reduces ICE fuel demand?","back":"Oil demand shifts left."}]},{"id":"ec214-l1-supply-equilibrium-v1","label":"Part 4 • Supply & Market Equilibrium","description":"Supply behavior, determinants, market clearing, surplus, shortage and shifts.","cards":[{"id":"qs","front":"What is quantity supplied (Qs)?","back":"The amount sellers are willing to sell in the market at a specific time."},{"id":"law-supply","front":"State the law of supply.","back":"Ceteris paribus: price rises→Qs rises; price falls→Qs falls."},{"id":"supply-slope","front":"Why does the supply curve slope upward?","back":"Because price and quantity supplied have a positive relationship, other things equal."},{"id":"input-price","front":"How do higher input prices affect supply?","back":"Production cost rises, so supply decreases and shifts left."},{"id":"technology","front":"How does better production technology affect supply?","back":"More efficient production increases supply and shifts it right."},{"id":"expect-supply","front":"If sellers expect a higher future product price, what may happen to current supply?","back":"They may wait to sell, reducing current supply."},{"id":"sellers","front":"How does a larger number of sellers affect market supply?","back":"Market supply increases."},{"id":"supply-related","front":"Can prices of related goods affect supply?","back":"Yes. The lecture lists them as a non-price supply determinant."},{"id":"supply-movement","front":"What causes movement along a supply curve?","back":"A change in the good’s own current price."},{"id":"supply-shift","front":"What causes a supply curve shift?","back":"A non-price determinant such as costs, technology, expectations, sellers, or related-good prices."},{"id":"equilibrium","front":"What defines market equilibrium?","back":"Quantity demanded equals quantity supplied: Qd = Qs."},{"id":"pe-qe","front":"What are Pe and Qe?","back":"Pe is equilibrium/market-clearing price; Qe is equilibrium quantity."},{"id":"surplus","front":"What happens when market price is above Pe?","back":"Qs>Qd creates a surplus, putting downward pressure on price."},{"id":"shortage","front":"What happens when market price is below Pe?","back":"Qd>Qs creates a shortage, putting upward pressure on price."},{"id":"equilibrium-stable","front":"Why is equilibrium called stable when D and S are unchanged?","back":"If price moves away from Pe, surplus/shortage pressure tends to move it back."},{"id":"new-equilibrium","front":"How do demand or supply shifts affect equilibrium?","back":"They create a new D–S intersection with a new equilibrium price and quantity."},{"id":"oil-war","front":"War/tension lowers oil production. What happens to equilibrium?","back":"Supply shifts left→equilibrium price rises and equilibrium quantity falls."}]}]};const root=window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};const b=root.ec214||(root.ec214={title:"EC214 Complete Lecture Flashcards",bankVersion:"ec214-v13.14",lectures:[]});b.lectures=Array.isArray(b.lectures)?b.lectures:[];b.lectures=b.lectures.filter(function(x){return x&&x.id!==lecture.id});b.lectures.push(lecture);})();